/* ---- test plumbing ------------------------------------------------------- */
static int failures = 0;
static int checks = 0;
#define CHECK(cond)                                              \
    do {                                                         \
        checks++;                                                \
        if(!(cond)) {                                            \
            failures++;                                          \
            printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); \
        }                                                        \
    } while(0)

/* The fake card: takes text until `capacity` bytes, then refuses. */
typedef struct {
    char text[8192];
    size_t used;
    size_t capacity;
    int calls;
} Card;

static bool card_sink(void* context, const char* text, size_t length) {
    Card* card = context;
    card->calls++;
    if(card->used + length > card->capacity) return false;
    memcpy(card->text + card->used, text, length);
    card->used += length;
    card->text[card->used] = '\0';
    return true;
}

static void card_reset(Card* card, size_t capacity) {
    memset(card, 0, sizeof(Card));
    card->capacity = capacity;
}

/* Feeds text to the loader a line at a time, the way the load scene does:
 * line endings removed, stopping once RAW_Data has been read. */
static void load_text(WiegandFileLoad* load, const char* text) {
    char line[8192];
    size_t used = 0;
    wiegand_file_load_begin(load);
    for(const char* p = text;; p++) {
        if(*p == '\n' || *p == '\0') {
            line[used] = '\0';
            if(wiegand_file_load_line(load, line)) return;
            used = 0;
            if(*p == '\0') return;
        } else if(*p != '\r') {
            line[used++] = *p;
        }
    }
}

/* Puts a made-up frame in the capture buffer, with a cycle counter value that
 * is nowhere near zero, as a real capture has. */
static void make_frame(int n, unsigned seed, uint32_t overflow, uint32_t glitches) {
    uint32_t time = 0xFFF00000u + seed * 977u; /* wraps mid-frame for long ones */
    for(int i = 0; i < n; i++) {
        seed = seed * 1103515245u + 12345u;
        data[i] = ((seed >> 16) & 1) != 0;
        data_fall[i] = time;
        data_rise[i] = time + (40u + (seed >> 28)) * WIEGAND_TICKS_PER_US;
        time += (2000u + ((seed >> 20) & 0x3F)) * WIEGAND_TICKS_PER_US;
    }
    bit_count = n;
    overflow_bits = overflow;
    glitch_count = glitches;
}

int main(int argc, char** argv) {
    static Card card;
    WiegandFileLoad load;
    static bool want_bits[MAX_BITS];
    static uint32_t want_fall[MAX_BITS];
    static uint32_t want_rise[MAX_BITS];

    /* 1. The exact text of a small frame. */
    data[0] = false;
    data[1] = true;
    data[2] = true;
    data_fall[0] = 1000;
    data_rise[0] = 3560;
    data_fall[1] = 129000;
    data_rise[1] = 131560;
    data_fall[2] = 257000;
    data_rise[2] = 259560;
    bit_count = 3;
    overflow_bits = 0;
    glitch_count = 2;
    card_reset(&card, sizeof(card.text) - 1);
    CHECK(wiegand_file_write(card_sink, &card));
    CHECK(
        strcmp(
            card.text,
            "Filetype: Flipper Wiegand Key File\n"
            "Version: 1\n"
            "Protocol: RAW\n"
            "Bits: 3\n"
            "Truncated_Bits: 0\n"
            "Glitches: 2\n"
            "RAW_Data: D0 0 2560 D1 128000 130560 D1 256000 258560 \n"
            "PACS_Binary: 011\n"
            "Hex_Right_Justified: 3\n"
            "Hex_Left_Justified: 6\n") == 0);

    /* 2. Save then load, every length: same bits, same edge times (relative to
     *    the first edge), same warnings. */
    for(int n = 1; n <= MAX_BITS; n++) {
        uint32_t overflow = (n == MAX_BITS) ? 5 : 0;
        uint32_t glitches = (uint32_t)(n % 4);
        make_frame(n, (unsigned)n * 7919u, overflow, glitches);
        for(int i = 0; i < n; i++) {
            want_bits[i] = data[i];
            want_fall[i] = data_fall[i] - data_fall[0];
            want_rise[i] = data_rise[i] - data_fall[0];
        }
        card_reset(&card, sizeof(card.text) - 1);
        CHECK(wiegand_file_write(card_sink, &card));
        CHECK(card.calls < 40); /* written in blocks, not a call per bit */

        load_text(&load, card.text);
        CHECK(load.has_raw);
        CHECK(bit_count == n);
        CHECK(load.declared_bits == n);
        CHECK(wiegand_file_load_bits_match(&load));
        CHECK(overflow_bits == overflow);
        CHECK(glitch_count == glitches);
        bool same = true;
        for(int i = 0; i < n; i++) {
            if(data[i] != want_bits[i] || data_fall[i] != want_fall[i] ||
               data_rise[i] != want_rise[i])
                same = false;
        }
        CHECK(same);
    }

    /* 3. A card that fills up part way: the save reports failure, wherever it
     *    stops. */
    {
        make_frame(48, 4242, 0, 0);
        card_reset(&card, sizeof(card.text) - 1);
        CHECK(wiegand_file_write(card_sink, &card));
        size_t full = card.used;
        for(size_t capacity = 0; capacity < full; capacity += 7) {
            card_reset(&card, capacity);
            CHECK(!wiegand_file_write(card_sink, &card));
        }
        card_reset(&card, full);
        CHECK(wiegand_file_write(card_sink, &card));
    }

    /* 4. A file from the original app: no warning lines, and it still loads. */
    if(argc == 2) {
        static char text[8192];
        FILE* file = fopen(argv[1], "rb");
        CHECK(file != NULL);
        if(file) {
            size_t got = fread(text, 1, sizeof(text) - 1, file);
            text[got] = '\0';
            fclose(file);
            load_text(&load, text);
            CHECK(bit_count == 48);
            CHECK(load.declared_bits == 48);
            CHECK(wiegand_file_load_bits_match(&load));
            CHECK(overflow_bits == 0 && glitch_count == 0);
            char hex[WIEGAND_HEX_TEXT_SIZE];
            wiegand_format_hex(data, bit_count, false, hex, sizeof(hex));
            CHECK(strcmp(hex, "00106803AE8D") == 0);
            CHECK(data_fall[0] == 0 && data_rise[0] == 2243 && data_fall[47] == 5879976);
        }
    } else {
        printf("FAIL: file_sim needs the path to examples/C1.wgn\n");
        failures++;
    }

    /* 5. A file that says one length and holds another is flagged. */
    load_text(&load, "Bits: 26\nRAW_Data: D0 0 2560 D1 128000 130560 D1 256000 258560 \n");
    CHECK(bit_count == 3);
    CHECK(!wiegand_file_load_bits_match(&load));

    /* 6. No "Bits:" line at all is not an error. Windows line endings are fine. */
    load_text(&load, "Protocol: RAW\r\nRAW_Data: D1 0 2560 D0 128000 130560 \r\n");
    CHECK(bit_count == 2 && data[0] && !data[1]);
    CHECK(load.declared_bits == -1 && wiegand_file_load_bits_match(&load));

    /* 7. More bits than the buffer holds: the extra ones are counted, on top
     *    of what the file already said was cut off. */
    {
        static char text[8192];
        size_t used = (size_t)snprintf(text, sizeof(text), "Truncated_Bits: 4\nRAW_Data: ");
        for(int i = 0; i < MAX_BITS + 3; i++) {
            used += (size_t)snprintf(
                text + used, sizeof(text) - used, "D%d %d %d ", i & 1, i * 128000, i * 128000 + 2560);
        }
        load_text(&load, text);
        CHECK(bit_count == MAX_BITS);
        CHECK(overflow_bits == 7);
    }

    /* 8. A file with no RAW_Data line loads nothing. */
    load_text(&load, "Filetype: Flipper Wiegand Key File\nVersion: 1\nBits: 26\n");
    CHECK(bit_count == 0 && !load.has_raw);

    printf("file simulation: %d checks, %d failures\n", checks, failures);
    return failures == 0 ? 0 : 1;
}
